    Distance drumRadius,
    double gearing,
    Distance minHeight, Distance maxHeight,
    Mass carriageMass,
    LinearVelocity maxVelocity, LinearAcceleration maxAccel,
    Gains gains) {}

// zero-alloc hot-loop idiom (VERBATIM from WPILib docs)
private final MutDistance m_lastDistance = Meters.mutable(0);
private final MutDistance m_delta = Meters.mutable(0);
public Distance calculateDelta(Distance current) {
  m_delta.mut_replace(current); m_delta.mut_minus(m_lastDistance);
  m_lastDistance.mut_replace(current); return m_delta;
}

public record Gains(double kP, double kI, double kD, double kS, double kV, double kA, double kG) {
  public static final Struct<Gains> struct = StructGenerator.genRecord(Gains.class);
  public Gains withKP(double kP) { return new Gains(kP, kI, kD, kS, kV, kA, kG); }
}
public record ElevatorConfig(String name, int leaderId, String canbus, double gearing, Gains gains) {
  public ElevatorConfig {                      // compact ctor = validation at construction
    if (gearing <= 0) throw new IllegalArgumentException(name + ": gearing must be > 0");
  }
}

public sealed interface MotorSpec permits TalonFX, Spark, Sim {
  record TalonFX(int id, String canbus) implements MotorSpec {}
  record Spark(int id, SparkModel model) implements MotorSpec {}
  record Sim(DCMotor gearbox, double moi) implements MotorSpec {}
}
// Java 21+ (WPILib 2027): compiler enforces every variant is handled
static MechanismIO create(MotorSpec s, MechanismConfig c) { return switch (s) {
  case MotorSpec.TalonFX t -> new TalonFXIO(t, c);
  case MotorSpec.Spark p   -> new SparkIO(p, c);
  case MotorSpec.Sim m     -> new SimIO(m, c);
}; }

